+pub(super) struct SupportedIndex {
+    pub name: &'static str,
+    pub symbol: &'static str,
+    // A conservative admission floor, NOT an upstream availability guarantee.
+    pub admitted_from: &'static str,
+}
+
+pub(super) const SUPPORTED: &[SupportedIndex] = &[
+    SupportedIndex { name: "NIFTY 50", symbol: "NIFTY", admitted_from: "1996-04-22" },
+    SupportedIndex { name: "NIFTY BANK", symbol: "BANKNIFTY", admitted_from: "2003-09-15" },
+    SupportedIndex { name: "NIFTY NEXT 50", symbol: "NIFTYNEXT50", admitted_from: "1997-01-01" },
+    SupportedIndex { name: "NIFTY 100", symbol: "NIFTY100", admitted_from: "2005-12-01" },
+    // Current official factsheets omit launch dates. Earlier observations remain
+    // held pending evidence; do not substitute the base date for the launch date.
+    SupportedIndex { name: "NIFTY 500", symbol: "NIFTY500", admitted_from: "2011-01-03" },
