+#[derive(Debug)]
+pub(super) struct Request {
+    pub task: NseIndexHistoryTask,
+    pub dates: BTreeSet<String>,
+}
+
+pub(super) fn requests(symbol: &str, dates: &BTreeSet<String>) -> AppResult<Vec<Request>> {
+    let index = SUPPORTED.iter().find(|i| i.symbol == symbol).ok_or("Unsupported index")?;
+    let mut pending = dates.iter().peekable();
+    let mut result = Vec::new();
+    while let Some(start) = pending.next() {
+        let end = parse_trade_date(start)?.checked_add_signed(Duration::days(365)).ok_or("Date overflow")?;
+        let mut selected = BTreeSet::from([start.clone()]);
+        while let Some(date) = pending.peek() {
+            if parse_trade_date(date)? > end { break; }
+            selected.insert((*date).clone());
+            pending.next();
+        }
+        result.push(Request {
+            task: NseIndexHistoryTask {
+                index_type: index.name.into(), symbol: symbol.into(),
+                from_date: start.clone(), to_date: selected.last().unwrap().clone(),
+            },
+            dates: selected,
+        });
+    }
+    Ok(result)
+}
+
+#[derive(Clone, Debug, PartialEq, Serialize)]
+pub(super) struct Observation {
+    pub date: String,
+    pub name: String,
+    pub prices: [f64; 4],
+    pub volume: Option<u64>,
+}
+
+#[derive(Default, Serialize)]
+pub(super) struct Normalized {
+    pub rows: Vec<Observation>,
+    pub held: BTreeMap<String, String>,
+    pub identical_duplicates: usize,
+    pub outside_unresolved_set: usize,
+}
+
+fn valid_prices(p: [f64; 4]) -> bool {
+    p.iter().all(|v| v.is_finite() && *v > 0.0 && *v < (i64::MAX as f64 / DEFAULT_SCALE as f64))
+        && p[1] >= p[0].max(p[3]) && p[2] <= p[0].min(p[3]) && p[1] >= p[2]
+}
+
+pub(super) fn normalize(bytes: &[u8], request: &Request, today: &str) -> AppResult<Normalized> {
+    let response: NseIndexHistoryResponse = serde_json::from_slice(bytes)
+        .map_err(|e| format!("Invalid NSE historical JSON: {e}"))?;
+    if response.error.unwrap_or(false) {
+        return Err(format!("NSE source refusal: {}", response.show_message.unwrap_or_default()));
+    }
+    let records = response.data.ok_or("NSE response missing data (availability unknown)")?;
+    let index = SUPPORTED.iter().find(|i| i.symbol == request.task.symbol).ok_or("Unsupported index")?;
+    let mut out = Normalized::default();
+    let mut seen = BTreeMap::<String, Observation>::new();
+    for record in records {
+        let name = record.index_name.ok_or("Missing response identity")?;
+        // No synthesized ticker or prefix matching is accepted here.
+        let family = nse_index_alias_family(&normalize_index_key(&name)).ok_or("Unknown index alias")?;
+        if family.canonical != index.symbol { return Err(format!("Wrong response identity: {name}")); }
+        let raw_date = record.timestamp.ok_or("Missing response date")?;
+        let date = normalize_trade_date_value(&raw_date).or_else(||
+            NaiveDate::parse_from_str(&raw_date, "%d-%b-%Y").ok().map(|d| d.to_string()))
+            .ok_or_else(|| format!("Invalid response date: {raw_date}"))?;
+        if date < request.task.from_date || date > request.task.to_date || date.as_str() > today {
+            return Err(format!("Out-of-range response date: {date}"));
+        }
+        if !request.dates.contains(&date) { out.outside_unresolved_set += 1; continue; }
+        let prices = [record.open.unwrap_or(0.0), record.high.unwrap_or(0.0), record.low.unwrap_or(0.0), record.close.unwrap_or(0.0)];
+        let reason = if date.as_str() < index.admitted_from {
+            Some("Pre-launch or earlier than evidenced admission floor")
+        } else if !valid_prices(prices) {
+            Some("Invalid, partial or close-only OHLC")
+        } else if record.traded_qty.is_some_and(|v| !v.is_finite() || v < 0.0 || v.fract() != 0.0 || v >= i64::MAX as f64) {
+            Some("Invalid volume")
+        } else { None };
+        if let Some(reason) = reason {
+            out.held.insert(date, reason.into());
+            continue;
+        }
+        let row = Observation { date: date.clone(), name, prices,
+            volume: record.traded_qty.filter(|v| *v > 0.0).map(|v| v as u64) };
+        if let Some(previous) = seen.get(&date) {
+            if previous.prices == row.prices && previous.volume == row.volume {
+                out.identical_duplicates += 1;
+            } else {
+                out.held.insert(date, "Conflicting duplicate date".into());
+            }
+        } else { seen.insert(date, row); }
+    }
+    out.rows = seen.into_values().filter(|r| !out.held.contains_key(&r.date)).collect();
+    Ok(out)
+}
+
+type Existing = HashMap<(String, String), Vec<([i64; 4], u64)>>;
+fn scaled(p: [f64; 4]) -> [i64; 4] { p.map(|v| (v * DEFAULT_SCALE as f64).round() as i64) }
+
+// Reads only the requested ranges of the relevant canonical/accepted alias files.
+fn existing_rows(database: &Path, symbols: &BTreeSet<String>, from: &str, to: &str) -> AppResult<Existing> {
+    let connection = Connection::open_with_flags(database, rusqlite::OpenFlags::SQLITE_OPEN_READ_ONLY).map_err(|e| e.to_string())?;
+    let binary = get_price_storage_mode(&connection) == PriceStorageMode::Binary;
+    let root = database.parent().ok_or("Missing database folder")?;
+    let mut existing = Existing::new();
+    for symbol in symbols {
+        let aliases: Vec<&str> = nse_index_alias_family(symbol).map(|f| f.symbols.to_vec()).unwrap_or_else(|| vec![symbol.as_str()]);
+        for alias in aliases {
+            if binary {
+                let path = root.join("eod_data/NSE_INDEX").join(format!("{alias}.eod"));
+                if !path.exists() { continue; }
+                let file = BinaryEodFile::open(&path)?;
+                if file.header.symbol != alias || file.header.exchange != "NSE_INDEX" || file.header.price_scale == 0 {
+                    return Err(format!("Existing index identity/scale mismatch: {}", path.display()));
+                }
+                for r in file.read_range(date_to_u32(from), date_to_u32(to))? {
+                    let p = [r.open, r.high, r.low, r.close].map(|v| v as f64 / file.header.price_scale as f64);
+                    if !valid_prices(p) { return Err(format!("Invalid existing index OHLC: {alias}@{}", r.date)); }
+                    existing.entry((symbol.clone(), u32_to_date(r.date))).or_default().push((scaled(p), r.volume));
+                }
+            } else {
+                let mut stmt = connection.prepare("SELECT date, open, high, low, close, volume FROM eod_prices WHERE exchange='NSE_INDEX' AND symbol=?1 AND date BETWEEN ?2 AND ?3").map_err(|e| e.to_string())?;
+                let rows = stmt.query_map(params![alias, from, to], |r| Ok((r.get::<_, String>(0)?, [r.get::<_, f64>(1)?, r.get(2)?, r.get(3)?, r.get(4)?], r.get::<_, i64>(5)?))).map_err(|e| e.to_string())?;
+                for row in rows {
+                    let (date, p, volume) = row.map_err(|e| e.to_string())?;
+                    if !valid_prices(p) || volume < 0 { return Err("Invalid existing index quotation".into()); }
+                    existing.entry((symbol.clone(), date)).or_default().push((scaled(p), volume as u64));
+                }
+            }
+        }
+    }
+    Ok(existing)
+}
