+#[derive(Default, Serialize)]
+pub(super) struct AdditiveOutcome {
+    pub identical: usize,
+    pub conflicts: usize,
+    pub invalid: usize,
+    pub inserted_candidates: usize,
+    pub details: Vec<String>,
+}
+
+// Called under the batch price-store permit immediately before journal creation.
+// A second call from replay protects against changed alias files as well.
+pub(super) fn guard_additive(database: &Path, files: &mut [ParsedBhavcopyFile]) -> AppResult<BTreeMap<String, AdditiveOutcome>> {
+    let mut symbols = BTreeSet::new();
+    let mut dates = BTreeSet::new();
+    for file in files.iter().filter(|f| f.exchange == "NSE_INDEX") {
+        for row in &file.rows { symbols.insert(row.symbol.clone()); dates.insert(row.trade_date.clone()); }
+    }
+    let Some(from) = dates.first() else { return Ok(BTreeMap::new()); };
+    let existing = existing_rows(database, &symbols, from, dates.last().unwrap())?;
+    let mut incoming = HashMap::<(String, String), Vec<([i64; 4], i64)>>::new();
+    for file in files.iter().filter(|f| f.exchange == "NSE_INDEX") {
+        for row in &file.rows {
+            incoming.entry((row.symbol.clone(), row.trade_date.clone())).or_default()
+                .push((scaled([row.open, row.high, row.low, row.close]), row.volume));
+        }
+    }
+    let mut accepted = HashSet::new();
+    let mut outcomes = BTreeMap::<String, AdditiveOutcome>::new();
+    for file in files.iter_mut().filter(|f| f.exchange == "NSE_INDEX") {
+        let out = outcomes.entry(file.trade_date.clone()).or_default();
+        file.rows.retain(|row| {
+            let key = (row.symbol.clone(), row.trade_date.clone());
+            let p = [row.open, row.high, row.low, row.close];
+            if !valid_prices(p) || row.volume < 0 {
+                out.invalid += 1; out.details.push(format!("{}: invalid OHLC/volume", row.symbol)); return false;
+            }
+            let p = scaled(p);
+            if incoming[&key].iter().any(|r| *r != (p, row.volume)) {
+                out.conflicts += 1; out.details.push(format!("{}: conflicting incoming duplicates", row.symbol)); return false;
+            }
+            if let Some(bars) = existing.get(&key) {
+                if bars.iter().all(|(other, volume)| *other == p && (row.volume == 0 || *volume == row.volume as u64)) {
+                    out.identical += 1;
+                } else { out.conflicts += 1; out.details.push(format!("{}: existing quotation preserved", row.symbol)); }
+                return false;
+            }
+            if !accepted.insert(key) { out.identical += 1; return false; }
+            out.inserted_candidates += 1;
+            true
+        });
+        file.max_volume = file.rows.iter().map(|r| r.volume as u64).max().unwrap_or(0);
+    }
+    Ok(outcomes)
+}
+
+pub(super) fn save_evidence(database: &Path, label: &str, bytes: &[u8]) -> AppResult<PathBuf> {
+    let directory = database.parent().ok_or("Missing database folder")?.join("bhavcopy_index_evidence");
+    fs::create_dir_all(&directory).map_err(|e| e.to_string())?;
+    let hash = format!("{:x}", Sha256::digest(bytes));
+    let path = directory.join(format!("{label}-{hash}.json"));
+    match OpenOptions::new().create_new(true).write(true).open(&path) {
+        Ok(mut file) => { file.write_all(bytes).map_err(|e| e.to_string())?; file.sync_all().map_err(|e| e.to_string())?; }
+        Err(e) if e.kind() == std::io::ErrorKind::AlreadyExists => {
+            if fs::read(&path).map_err(|e| e.to_string())? != bytes { return Err("Evidence hash collision or damaged evidence".into()); }
+        }
+        Err(e) => return Err(e.to_string()),
+    }
+    Ok(path)
+}
+
+fn fetch(client: &Client, url: &str, stop: &AtomicBool) -> AppResult<Vec<u8>> {
+    if stop.load(Ordering::SeqCst) { return Err("Index fallback cancelled".into()); }
+    // Serial, one attempt, 30-second client timeout, no browser or retry loop.
+    let response = client.get(url).header(reqwest::header::REFERER, NSE_INDEX_HISTORY_PAGE_URL)
+        .send().map_err(|e| format!("NSE source failure: {e}"))?;
+    if !response.status().is_success() { return Err(format!("NSE HTTP {} (availability unknown)", response.status())); }
+    let mut bytes = Vec::new();
+    response.take(8 * 1024 * 1024 + 1).read_to_end(&mut bytes).map_err(|e| e.to_string())?;
+    if bytes.len() > 8 * 1024 * 1024 { return Err("NSE response exceeds 8 MiB".into()); }
+    if stop.load(Ordering::SeqCst) { return Err("Index fallback cancelled".into()); }
+    Ok(bytes)
+}
+
+pub(super) fn stage_fallback(
+    app: &AppHandle, client: &Client, database: &Path, config: &BatchDownloadConfig,
+    dates: &BTreeSet<String>, staged: &mut Vec<StagedDownload>, results: &mut Vec<DownloadResult>, stop: &AtomicBool,
+) -> AppResult<()> {
+    if dates.is_empty() { return Ok(()); }
+    let symbols = SUPPORTED.iter().map(|i| i.symbol.to_string()).collect();
+    let existing = existing_rows(database, &symbols, dates.first().unwrap(), dates.last().unwrap())?;
+    let mut resolved = HashSet::<(String, String)>::new();
+    for ((symbol, date), bars) in &existing {
+        // Alias disagreement is visible as unresolved and rechecked before writes.
+        if bars.iter().all(|bar| bar == &bars[0]) { resolved.insert((symbol.clone(), date.clone())); }
+    }
+    for download in staged.iter().filter(|s| s.task.exchange == "NSE_INDEX") {
+        if let StagedDownloadContent::Csv(csv) = &download.content {
+            if let Ok(parsed) = parse_bhavcopy_csv(csv, "NSE_INDEX", &download.task.trade_date, &[]) {
+                if parsed.debug.is_none() {
+                    for row in parsed.rows {
+                        if valid_prices([row.open, row.high, row.low, row.close]) {
+                            resolved.insert((row.symbol, row.trade_date));
+                        }
+                    }
+                }
+            }
+        }
+    }
+    let mut fallback_rows = BTreeMap::<String, Vec<Observation>>::new();
+    let mut consecutive_failures = 0;
+    let mut circuit_open = false;
+    for index in SUPPORTED {
+        let unresolved = dates.iter().filter(|d| !resolved.contains(&(index.symbol.into(), (*d).clone()))).cloned().collect();
+        for request in requests(index.symbol, &unresolved)? {
+            if stop.load(Ordering::SeqCst) { return Err("Index fallback cancelled".into()); }
+            let scope = format!("{}..{} {}", request.task.from_date, request.task.to_date, index.symbol);
+            let url = build_nse_index_history_url(&request.task)?;
+            emit_progress(app, 60, format!("NSE historical fallback: {} ({})", scope, index.name));
+            let fetched = if circuit_open { Err("Source circuit open after refusal/repeated failures; request not attempted".into()) }
+                else { fetch(client, &url, stop) };
+            let mut raw_path = None;
+            let normalized = match fetched {
+                Ok(bytes) => {
+                    raw_path = Some(save_evidence(database, "response", &bytes)?);
+                    normalize(&bytes, &request, &today_trade_date())
+                }
+                Err(error) => Err(error),
+            };
+            let message;
+            let success;
+            match normalized {
+                Ok(normalized) => {
+                    consecutive_failures = 0;
+                    let acquired = normalized.rows.len();
+                    let missing = request.dates.len().saturating_sub(acquired + normalized.held.len());
+                    success = missing == 0 && normalized.held.is_empty();
+                    message = format!("Historical subset: acquired {acquired}, held {}, missing/unsupported {missing}, identical duplicates {}; volume absent/zero remains unknown; other indices unresolved", normalized.held.len(), normalized.identical_duplicates);
+                    let evidence = serde_json::to_vec_pretty(&serde_json::json!({
+                        "url": url, "symbol": index.symbol, "requestedDates": request.dates,
+                        "rawResponse": raw_path, "normalized": normalized,
+                        "volumePolicy": "null/zero = unknown; storage zero is not certified zero volume",
+                        "status": "STAGED_NOT_IMPORTED", "createdAt": chrono::Utc::now().to_rfc3339(),
+                    })).map_err(|e| e.to_string())?;
+                    save_evidence(database, "request", &evidence)?;
+                    for row in normalized.rows { fallback_rows.entry(row.date.clone()).or_default().push(row); }
+                }
+                Err(error) => {
+                    consecutive_failures += 1;
+                    circuit_open |= error.contains("403") || error.contains("429") || consecutive_failures >= 3;
+                    success = false;
+                    message = format!("Historical source failure: {error}");
+                    let evidence = serde_json::to_vec_pretty(&serde_json::json!({"url": url, "requestedDates": request.dates, "rawResponse": raw_path, "error": error, "createdAt": chrono::Utc::now().to_rfc3339()})).map_err(|e| e.to_string())?;
+                    save_evidence(database, "request-failed", &evidence)?;
+                }
+            }
+            results.push(DownloadResult { success, exchange: "NSE_INDEX".into(), trade_date: scope, rows_inserted: 0, max_volume: 0, message });
+        }
+    }
+    for (date, rows) in fallback_rows {
+        let mut writer = ::csv::Writer::from_writer(Vec::new());
+        writer.write_record(["INDEX_NAME", "INDEX_DATE", "OPEN_INDEX_VALUE", "HIGH_INDEX_VALUE", "LOW_INDEX_VALUE", "CLOSING_INDEX_VALUE", "VOLUME"]).map_err(|e| e.to_string())?;
+        for row in rows {
+            let [o,h,l,c] = row.prices;
+            writer.write_record([row.name, date.clone(), o.to_string(), h.to_string(), l.to_string(), c.to_string(), row.volume.unwrap_or(0).to_string()]).map_err(|e| e.to_string())?;
+        }
+        let csv = String::from_utf8(writer.into_inner().map_err(|e| e.to_string())?).map_err(|e| e.to_string())?;
+        staged.push(StagedDownload { task: DownloadTask { exchange: "NSE_INDEX".into(), trade_date: date, mode: config.mode.clone(), candidates: vec![], nse_index_history: None }, content: StagedDownloadContent::Csv(csv) });
+    }
+    Ok(())
+}
