+pub(super) fn validate_bse_code_rows(date: &str, rows: &[PriceRow], context: &ResolvedInstrumentContext) -> AppResult<()> {
+    if context.exchange != "BSE" || is_security_code(&context.current_symbol) { return Ok(()); }
+    let Some(code_row) = rows.iter().find(|r| is_security_code(&r.symbol)) else { return Ok(()); };
+    if rows.iter().any(|r| r.open != code_row.open || r.high != code_row.high || r.low != code_row.low
+        || r.close != code_row.close || r.volume != code_row.volume || r.open_interest != code_row.open_interest)
+    {
+        return Err(format!("Conflicting BSE security-code bars for {} on {date}; stored prices preserved. Review source history before charting.", context.current_symbol));
+    }
+    Ok(())
